// Preserve all saved overrides. Only reconcile Unity's verified size-mode correction.
using System;using System.IO;using System.Linq;using System.Text.RegularExpressions;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CyberOrbReconcile {
 static string Key(string guid,long id,string path,string value)=>guid+":"+id+":"+path+":"+value;
 static bool Correction(PropertyModification m)=>m.target is ParticleSystem&&m.target.name=="Shards"&&(m.propertyPath=="InitialModule.startSizeY.minMaxState"||m.propertyPath=="InitialModule.startSizeZ.minMaxState")&&m.value=="3"&&m.objectReference==null;
 public static string Run(){
  var scene=SceneManager.GetActiveScene();if(Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets"||scene.path!="Assets/Scenes/VFXWorkbench.unity")throw new Exception("Wrong scope/state");
  var project=Directory.GetParent(Application.dataPath).FullName;var output=Path.Combine(project,"VFXWork/Previews/CyberOrb/V3.2");var baseline=JObject.Parse(File.ReadAllText(Path.Combine(output,"Before.json")));var cam=Camera.main;
  if(cam==null||EditorJsonUtility.ToJson(cam)!=baseline["cameras"][0]["json"].Value<string>()||cam.transform.position.ToString()!=baseline["roots"][0]["pos"].Value<string>()||cam.transform.rotation.ToString()!=baseline["roots"][0]["rot"].Value<string>()||cam.transform.localScale!=Vector3.one)throw new Exception("Original camera changed; preserve author state");
  var roots=scene.GetRootGameObjects();if(roots.Length!=2||!roots.Any(g=>g.name=="Main Camera")||!roots.Any(g=>g.name=="CyberOrb_Demo"))throw new Exception("Unexpected scene roots; do not save");var demo=roots.Single(g=>g.name=="CyberOrb_Demo");
  if(demo.transform.position!=Vector3.zero||demo.transform.rotation!=Quaternion.identity||demo.transform.localScale!=Vector3.one||!demo.activeSelf||demo.transform.childCount!=3)throw new Exception("Demo root changed; do not save");
  var savedText=File.ReadAllText(Path.Combine(project,scene.path));var pattern=@"- target: \{fileID: (\d+), guid: ([a-f0-9]+), type: 3\}\s+propertyPath: ([^\r\n]+)\s+value:([^\r\n]*)\r?\n\s+objectReference: \{fileID: 0\}";
  var saved=new HashSet<string>(Regex.Matches(savedText,pattern).Cast<Match>().Select(m=>Key(m.Groups[2].Value,long.Parse(m.Groups[1].Value),m.Groups[3].Value.Trim(),m.Groups[4].Value.Trim())));var current=new HashSet<string>();var fixes=new List<PropertyModification>();
  var children=Enumerable.Range(0,3).Select(i=>demo.transform.GetChild(i).gameObject).ToArray();
  foreach(var g in children){if(!PrefabUtility.IsAnyPrefabInstanceRoot(g)||g.GetComponentsInChildren<MonoBehaviour>(true).Length>0)throw new Exception("Unexpected demo components");foreach(var m in PrefabUtility.GetPropertyModifications(g)??new PropertyModification[0]){string guid;long id;AssetDatabase.TryGetGUIDAndLocalFileIdentifier(m.target,out guid,out id);var key=Key(guid,id,m.propertyPath,m.value);if(saved.Contains(key))current.Add(key);else if(Correction(m))fixes.Add(m);else throw new Exception("Unrecognized author override; do not save: "+key);}}
  if(!saved.SetEquals(current)||fixes.Count!=4)throw new Exception("Saved overrides changed or correction count differs; do not save");
  var backup=Path.Combine(project,"VFXWork/Backups/CyberOrb/V3.2/VFXWorkbench-before-size-mode.snapshot");if(!File.Exists(backup))File.WriteAllText(backup,savedText);
  var changed=new List<string>();foreach(var v in new[]{"Impact","Shot"}){var path="Assets/PixelFX/CyberOrb/Prefabs/CyberOrb_"+v+".prefab";var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(path);var shards=prefab.GetComponentsInChildren<ParticleSystem>(true).Single(p=>p.name=="Shards");var so=new SerializedObject(shards);foreach(var axis in new[]{"Y","Z"}){var prop=so.FindProperty("InitialModule.startSize"+axis+".minMaxState");if(prop==null||prop.intValue!=0)throw new Exception("Unexpected asset size mode; preserve");prop.intValue=3;}so.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SavePrefabAsset(prefab);changed.Add(path);}
  foreach(var g in children){var mods=PrefabUtility.GetPropertyModifications(g)??new PropertyModification[0];PrefabUtility.SetPropertyModifications(g,mods.Where(m=>!Correction(m)).ToArray());}
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  var result=new{success=!scene.isDirty,changed,corrections=fixes.Count,preservedSavedOverrides=saved.Count,cameraPreserved=EditorJsonUtility.ToJson(cam)==baseline["cameras"][0]["json"].Value<string>(),reason="Unity synchronized unused startSize Y/Z curve modes to X=TwoConstants; no visible size/range change. Only these redundant task-owned overrides were removed.",backup};File.WriteAllText(Path.Combine(output,"SerializationReconcile.json"),JsonConvert.SerializeObject(result,Formatting.Indented));return JsonConvert.SerializeObject(result);
 }
}
